// 当前本人页面组合政治已知来源与S3唯一任务进度；不读取任意远方Office当前持有人。
#include "diplomacy_integration.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {
namespace {
using V=BoundaryValue;using A=V::Array;
DiplomacyPageRead page_read(const DiplomacyReadContext& c){return {c.common,c.common_catalog,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy,c.activity};}
StableId named(const CommonCatalog& catalog,const StableId& key){const auto* text=catalog.texts.find(key);return text?*text:StableId{};}
StableId offer_text(const StableId& status){if(status=="awaiting_delivery")return "提议尚未实际递交。";if(status=="presented")return "提议已实际递交，等对方明确答复。";if(status=="accepted_pending_ratification")return "对方已明确接受拟议条款，尚待必要认可与传达。";if(status=="refused")return "对方已明确拒绝这份条款。";return "原提议期限已过。";}
// 只用当前本人真实会话里的接触对象，不替使者选择远方新任代表。
StableId current_provider(const DiplomacyReadContext& c,const StableId& actor){for(const auto& session:c.interaction.interactions)if(session.actor_id==actor&&(session.phase=="say"||session.phase=="choice"))return session.context.provider_actor_id;return {};}
V action(const DiplomacyReadContext& c,const StableId& actor,const StableId& label,const DiplomacyCommand& command){auto quote=preview_diplomacy_business(c,actor,command);return boundary::obj({{"text",V{label}},{"command",V{diplomacy_command_kind(command)}},{"params",encode_diplomacy_command(command)},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}}});}
// 所有行旅按钮都是S1本次原报价返回的既有命令，外交叶不直接改变位置。
StableId append_navigation(const DiplomacyReadContext& c,const StableId& observer,const StableId& target,A& actions){if(!c.navigation)return "DiplomacyNavigationUnavailable";auto next=next_travel_command(c.common,c.navigation->state,c.navigation->catalog,c.navigation->services,observer,target);if(!next.ok)return next.error.original.code;if(!next.value.command)return {};V::Dict params;StableId kind,label="前往约定场所（下一段）";
    if(const auto* move=std::get_if<MoveLocalCommand>(&*next.value.command)){kind="move_local";params.emplace_back("place_id",V{move->place_id});}
    else{const auto& travel=std::get<TravelCommand>(*next.value.command);kind="travel";V destination;if(const auto* place=std::get_if<StableId>(&travel.destination))destination=V{*place};else{const auto point=std::get<PointI>(travel.destination);destination=V{A{V{point.x},V{point.y}}};}params.emplace_back("destination",std::move(destination));if(travel.has_via)params.emplace_back("via",boundary::string_array(travel.via));if(next.value.travel_quote)label+="，私钱"+std::to_string(next.value.travel_quote->cost);}
    actions.push_back(boundary::obj({{"text",V{label}},{"command",V{kind}},{"params",V{std::move(params)}},{"available",V{true}},{"code",V{StableId{}}}}));return {};
}
}
// 索引只含自己的已受领ID；进度、时耗和中断事实仍每次向原Task读口取得。
DiplomacyBusinessViewIndex make_diplomacy_business_view_index(const DiplomacyReadContext& c){DiplomacyBusinessViewIndex out;rebuild_diplomacy_view_index(page_read(c),out.politics);out.task_count=c.envoy_tasks.envoy_contracts.size();if(c.diplomacy_catalog.v2)for(const auto& row:c.diplomacy_catalog.v2->delegation_policies.rows())out.delegation_ids_by_envoy[row.second.envoy_actor_id].push_back(row.first);for(const auto& row:c.envoy_tasks.envoy_contracts.rows())out.task_ids_by_actor[row.second.acceptance.envoy_actor_id].push_back(row.first);for(auto& person:out.task_ids_by_actor)std::sort(person.second.begin(),person.second.end(),[&](const auto& a,const auto& b){const auto* x=c.tasks.tasks.find(a);const auto* y=c.tasks.tasks.find(b);const bool active_x=x&&(x->status=="active"||x->status=="ready");const bool active_y=y&&(y->status=="active"||y->status=="ready");return active_x!=active_y?active_x>active_y:a>b;});return out;}
Outcome<V> query_diplomacy_business(const DiplomacyReadContext& c,const StableId& observer,const StableId& place){
    if(observer!=c.common.state().metadata.player_actor_id)return {false,{},common_failure("DiplomacyObserverMismatch").error};if(!c.diplomacy_catalog.enabled)return {false,{},common_failure("DiplomacyUnavailable").error};if(!c.view_index||c.view_index->task_count!=c.envoy_tasks.envoy_contracts.size())return {false,{},common_failure("StaleDiplomacyViewIndex").error};auto page=build_diplomacy_page_view(page_read(c),c.view_index->politics,observer,place);if(!page.ok)return {false,{},page.error};A rows;bool truncated=page.value.truncated;std::set<StableId> accepted_authorities;DiplomaticMissionAccess missions(c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy);std::optional<DiplomaticReportAccess> reports;if(c.diplomacy.version==2&&c.diplomacy.v2)reports.emplace(DiplomaticHistoryRead{c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy},*c.diplomacy.v2);
    auto mine=c.view_index->task_ids_by_actor.find(observer);if(mine!=c.view_index->task_ids_by_actor.end()){truncated=truncated||mine->second.size()>128;for(std::size_t i=0;i<std::min<std::size_t>(128,mine->second.size());++i){auto progress=query_envoy_task_progress(c.common,c.tasks,c.envoy_tasks,missions,missions,mine->second[i],reports?&*reports:nullptr);if(!progress.ok)return {false,{},progress.error};const auto& task=progress.value;accepted_authorities.insert(task.mission_authority_fact_id);A actions;StableId description,navigation_code;for(const auto& line:envoy_task_progress_lines(task)){if(!description.empty())description+='\n';description+=line;}
        if(task.status=="active"||task.status=="ready"){if(task.action_id)actions.push_back(boundary::obj({{"text",V{"继续半日"}},{"command",V{"advance"}},{"params",V{V::Dict{}}},{"available",V{true}},{"code",V{StableId{}}}}));actions.push_back(action(c,observer,"取消本人使者责任",DiplomaticEnvoyCancelCommand{task.task_id,c.common.revision()}));if(task.status=="active"&&!task.action_id&&c.common.tick()<task.delivery_expires_tick){if(place==task.delivery_site_id){const auto provider=current_provider(c,observer);if(!provider.empty())actions.push_back(action(c,observer,"当面递交这份提议",DiplomaticEnvoyDeliverCommand{task.task_id,provider,c.common.revision()}));else description+="\n请先与有权接收的代表实际会面，再办理当面递交。";}else navigation_code=append_navigation(c,observer,task.delivery_site_id,actions);}}
        if(task.status=="ready"&&task.return_report_required&&!task.action_id){if(place==task.report_site_id){const auto provider=current_provider(c,observer);if(!provider.empty())actions.push_back(action(c,observer,"向原发令公职当面返报",DiplomaticEnvoyReportCommand{task.task_id,provider,c.common.revision()}));else description+="\n已实际递交；请与原报告公职的现任接收者会面，办理返报。";}else navigation_code=append_navigation(c,observer,task.report_site_id,actions);}
        rows.push_back(boundary::obj({{"id",V{task.task_id}},{"source_fact_id",V{task.acceptance_fact_id}},{"display_name",V{task.display_name}},{"text",V{"本人已受领的使者责任"}},{"terms_text",V{description}},{"expires_tick",V{task.delivery_expires_tick}},{"task_progress",encode_envoy_task_progress(task)},{"navigation_code",V{navigation_code}},{"actions",V{std::move(actions)}}}));
    }}
    if(c.diplomacy_catalog.v2&&c.diplomacy.v2){auto policies=c.view_index->delegation_ids_by_envoy.find(observer);if(policies!=c.view_index->delegation_ids_by_envoy.end()){
        truncated=truncated||policies->second.size()>128;const auto provider=current_provider(c,observer);
        for(std::size_t i=0;i<std::min<std::size_t>(128,policies->second.size());++i){const auto* policy=c.diplomacy_catalog.v2->delegation_policies.find(policies->second[i]);if(!policy)return {false,{},common_failure("InvalidDiplomaticViewSource").error};
            const auto* office=c.organization.offices.find(policy->issuer_office_id);if(provider.empty()||!office||!office->holder_actor_id||*office->holder_actor_id!=provider)continue;
            DiplomaticPresentRead read{c.common,c.organization,c.organization_catalog,c.diplomacy_catalog,c.diplomacy,c.interaction,c.interaction_catalog,c.interaction_access};
            auto candidate=propose_diplomatic_delegation_npc(read,c.common_catalog,c.activity,provider,policy->id);if(!candidate.ok)return {false,{},candidate.error};if(!candidate.value)continue;
            A actions{boundary::obj({{"text",V{"等候对方说明委任半日"}},{"command",V{"advance"}},{"params",V{V::Dict{}}},{"available",V{true}},{"code",V{StableId{}}}})};
            rows.push_back(boundary::obj({{"id",V{"delegation:"+policy->id}},{"source_fact_id",V{StableId{}}},{"display_name",V{"当面公务"}},{"text",V{"正在与可签发使命的公职代表会面"}},{"terms_text",V{"可等候对方实际说明。收到具名使命后，是否受领仍由本人决定。"}},{"actions",V{std::move(actions)}}}));
        }
    }}
    for(const auto& option:page.value.proposal_options){A actions;DiplomaticProposeCommand cmd{option.choice.authority,option.choice.policy_id,option.choice.terms_id};actions.push_back(action(c,observer,"提出这份通行条款",cmd));rows.push_back(boundary::obj({{"id",V{"option:"+option.choice.authority.office_id+":"+option.choice.policy_id+":"+option.choice.terms_id}},{"source_fact_id",V{StableId{}}},{"display_name",V{named(c.common_catalog,option.policy_name_key)}},{"text",V{"当前公职允许提出的条款"}},{"terms_text",V{named(c.common_catalog,option.terms_name_key)+"。提出和呈递均不等于对方接受或已获通行许可。"}},{"actions",V{std::move(actions)}}}));}
    for(const auto& offer:page.value.offers){A actions;const auto* policy=c.diplomacy_catalog.mission_policies.find(offer.policy_id);const auto* terms=c.diplomacy_catalog.passage_terms.find(offer.terms_id);if(!policy||!terms)return {false,{},common_failure("InvalidDiplomaticViewSource").error};
        if(offer.known_status=="awaiting_delivery"&&offer.envoy_actor_id==observer){if(offer.mission_authority_fact_id.empty()){if(policy->task_terms)actions.push_back(action(c,observer,"签发本人使者责任",DiplomaticMissionCommand{offer.offer_id,offer.source_fact_id,offer.offer_revision}));else actions.push_back(action(c,observer,"本人当面呈递",DiplomaticPresentCommand{offer.offer_id,offer.source_fact_id,offer.offer_revision,offer.terms_revision}));}else if(!accepted_authorities.count(offer.mission_authority_fact_id))actions.push_back(action(c,observer,"明确受领使者责任",DiplomaticEnvoyAcceptCommand{offer.mission_authority_fact_id,c.common.revision()}));}
        if(offer.known_status=="presented"&&offer.envoy_actor_id!=observer){actions.push_back(action(c,observer,"明确接受拟议条款",DiplomaticReplyCommand{offer.offer_id,offer.source_fact_id,offer.offer_revision,offer.terms_revision,DiplomaticReplyKind::accept}));actions.push_back(action(c,observer,"明确拒绝拟议条款",DiplomaticReplyCommand{offer.offer_id,offer.source_fact_id,offer.offer_revision,offer.terms_revision,DiplomaticReplyKind::refuse}));}
        // Waiting advances the original world once; it grants no reply or treaty authority.
        // Only the actual envoy's known pending offer and current lawful face-to-face receiver qualify.
        if(offer.known_status=="presented"&&offer.envoy_actor_id==observer){const auto provider=current_provider(c,observer);if(!provider.empty()&&preview_diplomacy_business(c,provider,DiplomaticReplyCommand{offer.offer_id,offer.source_fact_id,offer.offer_revision,offer.terms_revision,DiplomaticReplyKind::accept}).ok)actions.push_back(boundary::obj({{"text",V{"等候答复半日"}},{"command",V{"advance"}},{"params",V{V::Dict{}}},{"available",V{true}},{"code",V{StableId{}}}}));}
        auto detail=named(c.common_catalog,offer.terms_name_key)+"，第"+std::to_string(offer.terms_revision)+"版。拟议有效期"+std::to_string(terms->duration_ticks)+"半日，届满前"+std::to_string(terms->expiry_notice_ticks)+"半日通知；尚未生效。";
        rows.push_back(boundary::obj({{"id",V{offer.offer_id}},{"source_fact_id",V{offer.source_fact_id}},{"display_name",V{named(c.common_catalog,offer.policy_name_key)}},{"text",V{offer_text(offer.known_status)}},{"terms_text",V{detail}},{"expires_tick",V{offer.expires_tick}},{"actions",V{std::move(actions)}}}));
    }
    return {true,boundary::obj({{"ok",V{true}},{"rows",V{std::move(rows)}},{"truncated",V{truncated}}}),{}};
}
}
